def fullDemo() -> None:
    """
    Full demo to check class is working
    """
    BibleOrgSysGlobals.introduceProgram( __name__, PROGRAM_NAME_VERSION, LAST_MODIFIED_DATE )

    # Demo the Latin converter
    for testHTMLStr,expectedResultStr in ((' viis ',' ways '), (' vivunt ',' they_live ')):
        resultStr = translateLatin( testHTMLStr )
        assert resultStr == expectedResultStr, f"translateLatin({testHTMLStr}) gave {resultStr=} instead of {expectedResultStr=}"

    # Check for words accidentally placed in both language tables.
    from BibleOrgSys.Reference.LutherGermanToEnglish import GERMAN_WORD_MAP

    knownCommonWords = (
        'absorpta','an','bis','bis,','bis;','Christi','Christo','Christum','Christus','Da','da','da!','da)','da,','da.',
        'da:','da;','da<','da?','das','das!','das)','das,','das.','das:','das;','das<','das?','dem','des','des,','die',
        'die!','die)','die,','die.','die:','die;','die<','die?','Dies','dies','es','es,','es.','es:','es;','es<','es?',
        'esse','esse!','esse)','esse,','esse.','esse:','esse;','esse<','esse?','esset','Evangelium','findunt','habe',
        'habet','Herodes','hin','hin,','hin.','hin:','hin?','innern','Jeremia','junge','jungens','lege','litt.','Manasse',
        'Manasse,','Manasse.','Mich','Ninive','Ob','ob','Ob!','Ob)','Ob,','Ob.','Ob:','Ob;','Ob<','Ob?','Petrus','Pharao',
        'Pharao,','Philippus','Pilatus','reget','regnet','Tau','Tau!','Tau)','Tau,','Tau.','Tau:','Tau;','Tau<','Tau?',
        'tot','Tu','tu','Tu,','tu,','Tu.','tu.','tu:','tu;','tu<','tu?',
        )
    strippedGermanWords = {word.strip() for word, _ in GERMAN_WORD_MAP}
    strippedLatinWords = {word.strip() for word, _ in LATIN_WORD_MAP}
    unexpectedCommonWords = (strippedGermanWords & strippedLatinWords) - set(knownCommonWords)
    assert not unexpectedCommonWords, f"Words in both German and Latin tables: {sorted(unexpectedCommonWords)}"
# end of VulgateLatinToEnglish.fullDemo

if __name__ == '__main__':
    from multiprocessing import set_start_method, freeze_support
    set_start_method('fork') # The default was changed on POSIX systems from 'fork' to 'forkserver' in Python3.14
    freeze_support() # Multiprocessing support for frozen Windows executables

    # Configure basic Bible Organisational System (BOS) set-up
    parser = BibleOrgSysGlobals.setup( SHORT_PROGRAM_NAME, PROGRAM_VERSION, LAST_MODIFIED_DATE )
    BibleOrgSysGlobals.addStandardOptionsAndProcess( parser )

    fullDemo()

    BibleOrgSysGlobals.closedown( PROGRAM_NAME, PROGRAM_VERSION )
